{
  "namespace": "npdev.seed",
  "dslVersion": "1.0.0",
  "version": "0.1.1",
  "concepts": [
    {
      "name": "Customer",
      "ui": {
        "label": "Customer"
      },
      "fields": [
        {
          "name": "id",
          "type": "uuid",
          "id": true,
          "required": true
        },
        {
          "name": "customerRef",
          "type": "string",
          "required": true,
          "ui": {
            "label": "Customer reference number"
          }
        },
        {
          "name": "givenName",
          "type": "string",
          "required": true,
          "ui": {
            "label": "Given name"
          },
          "renamedFrom": "firstName"
        },
        {
          "name": "lastName",
          "type": "string",
          "required": true,
          "ui": {
            "label": "Last name"
          }
        }
      ],
      "invariants": [
        {
          "name": "CustomerRefUnique",
          "type": "unique",
          "fields": [
            "customerRef"
          ]
        }
      ]
    },
    {
      "name": "Order",
      "ui": {
        "label": "Order"
      },
      "fields": [
        {
          "name": "id",
          "type": "uuid",
          "id": true,
          "required": true
        },
        {
          "name": "customerId",
          "type": "reference",
          "required": true,
          "ui": {
            "label": "Customer"
          },
          "reference": {
            "target": "Customer",
            "displayField": "lastName"
          }
        },
        {
          "name": "orderedAt",
          "type": "datetime",
          "required": true,
          "ui": {
            "label": "Ordered at"
          }
        }
      ]
    }
  ]
}
